void __RPC_USER HSTRING_UserFree(ULONG *flags, HSTRING *str)
{
    TRACE("%s, %s.\n", debugstr_user_flags(flags), debugstr_hstring(*str));

    if (LOWORD(*flags) == MSHCTX_INPROC)
        WindowsDeleteString(*str);
}

